INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-08-03' FROM countries WHERE name_en = 'Israel';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'en', 'Centralized clearance — SHAAM allocation-number system (domestic B2B only)', 'This deep-dive page reflects publicly available Israel Tax Authority guidance and industry reporting as of August 2026 and is provided for general awareness, not legal or tax advice. The threshold schedule has already been accelerated once and could change again — confirm current requirements directly with the Israel Tax Authority (ITA) or your integration provider before building against them.', 'Israel''s mandate was legislated in 2023 but rolled out via a shrinking invoice threshold rather than taxpayer-size waves: a genuine no-rejection pilot from May 2024 above NIS 25,000, tightening enforcement from January 2025 at NIS 20,000, then an acceleration announced in December 2025 that compressed the remaining five-year rollout into two, reaching NIS 10,000 in January 2026 and the permanent floor of NIS 5,000 in June 2026.', 'SHAAM invoices are submitted as structured JSON via API, or entered manually through the ITA''s web portal — there is no separate legacy Israeli schema, and no UBL or XML authoring step as seen in some other mandates in this tracker.', 'Israel''s mandate is domestic B2B only: it applies to invoices between VAT-registered businesses inside Israel above the current threshold. B2C, B2G, and cross-border (export/import) transactions are explicitly out of scope — a narrower reach than most CTC mandates covered in this tracker.', 'Getting compliant means confirming whether your invoice volumes clear the current threshold, choosing a submission route, mapping your invoice data to SHAAM''s required fields, and building in contingency handling for when the system or your connection is unavailable.', 'Israel has no published, quantified fine schedule for SHAAM non-compliance. Instead, enforcement runs through the VAT system itself: from 2025, the ITA can refuse to issue an allocation number for an irregular invoice, and without a valid allocation number the buyer cannot deduct the input VAT — turning invoice compliance into a precondition for tax recovery rather than a separately fined offense.', 'Israel''s SHAAM allocation-number system has applied to domestic B2B invoices above a shrinking threshold since a genuine no-rejection pilot began in May 2024. Full ITA scrutiny and refusal powers activated in January 2025, and an accelerated schedule announced in December 2025 brought the threshold down to its permanent floor of NIS 5,000 by June 2026 — roughly 18 months ahead of the original 2028 timeline. B2C, B2G, and cross-border transactions remain outside the mandate''s scope.', '🇮🇱' FROM countries WHERE name_en = 'Israel';
