INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', 'B2B only', 'No B2C, B2G, or cross-border scope');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Israel';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Format & standard', '[["Submission format", "Structured JSON via API, or manual entry through the ITA web portal"], ["Key identifier", "9-digit Allocation Number issued per cleared invoice"], ["VAT return reference", "Allocation numbers reported on Form PCN874"], ["Legal basis", "Economic Efficiency Law (Budget Amendments) 2023-2024, amending the VAT Law 1975"]]', 'There is no invoice-authoring standard to learn here comparable to UBL or Peppol — the integration work is almost entirely about the API connection and field mapping, since the underlying format is plain structured JSON.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Israel';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Identifiers & registration', '[["Taxpayer identity", "Israeli VAT registration number"], ["Access routes", "Direct API integration, or the free gov.il manual portal"], ["Accredited software field", "Accounting_Software_Number, required when submitting via certified accounting software"], ["Request portal", "gov.il — request an allocation number for a tax invoice"]]', 'The Accounting_Software_Number field matters specifically for businesses using accredited accounting software rather than a custom integration — confirm with your software vendor whether this is populated automatically.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Israel';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Mandatory content & archiving', '[["Line-item detail", "Not required in the initial submission -- a lighter data footprint than most CTC mandates in this tracker"], ["Retention period", "7 years"], ["Downtime contingency", "Section 40B allows retroactive allocation-number requests when SHAAM or a business''s own systems are unavailable"], ["Verification service", "gov.il -- verify vendor invoice information, for checking a supplier''s allocation number"]]', 'The absence of a line-item submission requirement is a genuine simplification compared to peer mandates -- but the 7-year retention period and Section 40B contingency process still deserve real process design, not an afterthought.', NULL);
INSERT INTO deep_dive_lifecycle_cards (country_id, section, sort_order, display_style) SELECT id, 'scope_transmission', 0, 'pills' FROM countries WHERE name_en = 'Israel';
INSERT INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 'en', 'The clearance flow', 'Every in-scope SHAAM invoice moves through the same sequence:', 'The buyer needs a valid allocation number on the invoice before they can deduct the input VAT -- this is what makes SHAAM a genuine clearance model rather than a post-transaction reporting system.');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 0, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Invoice drafted');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 1, 0);
