INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Delivered to buyer + reported on VAT return');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Israel';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'The threshold phase-down', '[["From 5 May 2024", "Pilot -- above NIS 25,000, no rejections for content"], ["From 1 Jan 2025", "NIS 20,000 -- full ITA scrutiny and refusal powers activate"], ["From 1 Jan 2026", "NIS 10,000 -- accelerated schedule, skipping the planned NIS 15,000 step"], ["From 1 Jun 2026", "NIS 5,000 -- the permanent floor, no further reductions currently scheduled"]]', 'The threshold-based rollout is a genuinely different mechanic from every other mandate in this tracker -- there are no taxpayer-size waves here, just a shrinking invoice-value floor that eventually catches nearly all domestic B2B activity.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Israel';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'What''s explicitly out of scope', '[["B2C sales", "Not covered -- consumer-facing invoices stay outside SHAAM"], ["B2G transactions", "Not covered by this mandate"], ["Exports and imports", "Cross-border trade is excluded"], ["Below-threshold B2B", "Domestic B2B invoices under the current NIS threshold remain outside the requirement"]]', 'This narrower B2B-only scope is worth double-checking against your own transaction mix -- a business with mostly B2C or export revenue may have far less SHAAM exposure than the headline "mandatory e-invoicing" framing suggests.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'Israel';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🧾 VAT deduction denial — the real enforcement engine', NULL, NULL, 'Israel enforces SHAAM compliance almost entirely through the VAT system rather than direct fines: without a valid allocation number, the buyer cannot deduct the input VAT on that invoice. A supplier who fails to obtain one doesn''t face a penalty directly — their invoice simply becomes worthless to VAT-registered customers, which drives compliance without a published fine schedule.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Israel';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🔍 The ITA can now say no', NULL, NULL, 'Since January 2025, the pilot''s no-rejection grace has ended: the ITA can scrutinize submissions and refuse to issue an allocation number for an invoice it deems irregular, with a formal review and hearing process available within 2 business days of a refusal.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Israel';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '⚠️ No published fine schedule', NULL, NULL, 'Unlike several mandates in this tracker, no source reviewed here documents a quantified fixed-fine schedule for SHAAM non-compliance -- the VAT deduction mechanism above appears to be the primary enforcement lever. Confirm directly with the ITA if a formal penalty structure is introduced.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Israel';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm whether the current threshold applies to you', 'Check your typical domestic B2B invoice values against the current NIS 5,000 floor -- remember B2C, B2G, and cross-border invoices are out of scope regardless of value.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Israel';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Choose your submission route', 'Higher-volume businesses should integrate directly via the SHAAM API; the free gov.il manual portal suits lower-volume submitters without in-house development resources.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Israel';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Map your invoice data to the required JSON fields', 'Line-item detail isn''t required in the initial submission, which simplifies the mapping compared to peer mandates -- but taxpayer identity and invoice-value fields still need to be accurate.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Israel';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Populate the Accounting_Software_Number field if applicable', 'If you submit through accredited accounting software rather than a custom integration, confirm this field is populated correctly -- check with your software vendor rather than assuming.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Israel';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Build a contingency process for system downtime', 'Section 40B allows retroactive allocation-number requests when SHAAM or your own systems are unavailable -- design this handling in advance rather than improvising during an outage.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 5 FROM countries WHERE name_en = 'Israel';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Report allocation numbers on Form PCN874', 'Confirm your VAT return process references the allocation numbers correctly -- an invoice without one is not just a compliance risk, it blocks your customer''s input VAT deduction.');
