INSERT INTO deep_dive_portal_translations (portal_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_portals), 'en', 'Israel Tax Authority — request an allocation number');
INSERT INTO deep_dive_portals (country_id, url, sort_order) SELECT id, 'https://www.gov.il/en/service/verify-vendor-invoice-information', 1 FROM countries WHERE name_en = 'Israel';
INSERT INTO deep_dive_portal_translations (portal_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_portals), 'en', 'Israel Tax Authority — verify vendor invoice information');
